import Foundation
import NIO
import NIOFoundationCompat
import CryptoKit

// MARK: - Encrypted Storage Layer
class SecureStorage {
    private let encryptionKey: SymmetricKey
    private var store: [String: Data] = [:]

    init(key: SymmetricKey) {
        self.encryptionKey = key
    }

    func save(key: String, object: NSDictionary) throws {
        let archived = try NSKeyedArchiver.archivedData(withRootObject: object, requiringSecureCoding: true)
        let encrypted = try encrypt(data: archived)
        store[key] = encrypted
    }

    func load(key: String) throws -> NSDictionary? {
        guard let encrypted = store[key] else { return nil }
        let decrypted = try decrypt(data: encrypted)
        let unarchiver = try NSKeyedUnarchiver(forReadingFrom: decrypted)
        unarchiver.requiresSecureCoding = true
        return unarchiver.decodeObject(of: NSDictionary.self, forKey: NSKeyedArchiveRootObjectKey)
    }

    // Authenticated encryption (AES-GCM) replaces the insecure XOR cipher.
    private func encrypt(data: Data) throws -> Data {
        let sealedBox = try AES.GCM.seal(data, using: encryptionKey)
        guard let combined = sealedBox.combined else {
            throw NSError(domain: "SecureStorage", code: -1, userInfo: [NSLocalizedDescriptionKey: "Encryption failed"])
        }
        return combined
    }

    private func decrypt(data: Data) throws -> Data {
        let sealedBox = try AES.GCM.SealedBox(combined: data)
        return try AES.GCM.open(sealedBox, using: encryptionKey)
    }
}

// MARK: - Message Protocol
struct ChatEnvelope {
    let version: UInt8
    let messageType: UInt8  // 0x01 = text, 0x02 = presence, 0x03 = session_restore
    let payload: Data
}

// MARK: - Session Codec
class SessionCodec {
    private let storage: SecureStorage

    init(storage: SecureStorage) {
        self.storage = storage
    }

    func decodeEnvelope(from data: Data) -> ChatEnvelope? {
        guard data.count >= 3 else { return nil }
        let version = data[0]
        let messageType = data[1]
        let lengthByte = UInt16(data[2]) << 8 | UInt16(data.count > 3 ? data[3] : 0)
        guard data.count >= Int(lengthByte) + 4 else { return nil }
        let payload = data.subdata(in: 4..<(4 + Int(lengthByte)))
        return ChatEnvelope(version: version, messageType: messageType, payload: payload)
    }

    func processEnvelope(_ envelope: ChatEnvelope, sessionId: String) throws -> String? {
        switch envelope.messageType {
        case 0x01:
            return processTextMessage(envelope.payload)
        case 0x02:
            return processPresence(envelope.payload)
        case 0x03:
            return try processSessionRestore(envelope.payload, sessionId: sessionId)
        default:
            return nil
        }
    }

    private func processTextMessage(_ payload: Data) -> String? {
        return String(data: payload, encoding: .utf8)
    }

    private func processPresence(_ payload: Data) -> String? {
        guard let status = String(data: payload, encoding: .utf8) else { return nil }
        return "[presence] \(status)"
    }

    private func processSessionRestore(_ payload: Data, sessionId: String) throws -> String? {
        // Session restore: client sends serialized session state for migration
        // The payload is the encrypted session blob from the client's local cache
        let restoredState = try restoreSessionState(from: payload, sessionId: sessionId)
        return restoredState
    }

    private func restoreSessionState(from payload: Data, sessionId: String) throws -> String? {
        // Validate the session token prefix
        guard payload.count > 16 else { return nil }
        let tokenPrefix = payload.subdata(in: 0..<16)
        let sessionData = payload.subdata(in: 16..<payload.count)

        // Verify token matches expected format (first 16 bytes = session fingerprint)
        let expectedPrefix = sessionId.data(using: .utf8)!.prefix(16)
        guard tokenPrefix == expectedPrefix.prefix(min(16, expectedPrefix.count)).paddedTo(16) else {
            return nil
        }

        // Deserialize the session state using secure coding with class allowlist
        let unarchiver = try NSKeyedUnarchiver(forReadingFrom: sessionData)
        unarchiver.requiresSecureCoding = true
        guard let dict = unarchiver.decodeObject(of: NSDictionary.self, forKey: NSKeyedArchiveRootObjectKey) else {
            return nil
        }

        try storage.save(key: "session_\(sessionId)", object: dict)
        return "[session_restored] \(dict["username"] ?? "unknown")"
    }
}

// MARK: - Channel Handler
final class ChatHandler: ChannelInboundHandler {
    typealias InboundIn = ByteBuffer
    typealias OutboundOut = ByteBuffer

    private let codec: SessionCodec
    private let sessionId: String

    init(codec: SessionCodec, sessionId: String) {
        self.codec = codec
        self.sessionId = sessionId
    }

    func channelRead(context: ChannelHandlerContext, data: NIOAny) {
        var buffer = unwrapInboundIn(data)
        guard let bytes = buffer.readData(length: buffer.readableBytes) else { return }

        guard let envelope = codec.decodeEnvelope(from: bytes) else {
            sendError(context: context, message: "Invalid envelope")
            return
        }

        do {
            if let response = try codec.processEnvelope(envelope, sessionId: sessionId) {
                sendMessage(context: context, message: response)
            }
        } catch {
            sendError(context: context, message: "Processing error")
        }
    }

    private func sendMessage(context: ChannelHandlerContext, message: String) {
        var buffer = context.channel.allocator.buffer(capacity: message.utf8.count)
        buffer.writeString(message)
        context.writeAndFlush(wrapOutboundOut(buffer), promise: nil)
    }

    private func sendError(context: ChannelHandlerContext, message: String) {
        sendMessage(context: context, message: "[error] \(message)")
    }
}

// MARK: - Helpers
extension Data {
    func paddedTo(_ length: Int) -> Data {
        if self.count >= length { return self.prefix(length) }
        var padded = self
        padded.append(Data(repeating: 0, count: length - self.count))
        return padded
    }
}

// MARK: - Server Bootstrap
func startChatServer(host: String = "0.0.0.0", port: Int = 8443) throws {
    let group = MultiThreadedEventLoopGroup(numberOfThreads: System.coreCount)
    // Generate a random 256-bit key at startup instead of a hardcoded key.
    let storageKey = SymmetricKey(size: .bits256)
    let storage = SecureStorage(key: storageKey)

    let bootstrap = ServerBootstrap(group: group)
        .childChannelInitializer { channel in
            let sessionId = UUID().uuidString
            let codec = SessionCodec(storage: storage)
            return channel.pipeline.addHandler(ChatHandler(codec: codec, sessionId: sessionId))
        }

    let channel = try bootstrap.bind(host: host, port: port).wait()
    print("Chat server running on \(channel.localAddress!)")
    try channel.closeFuture.wait()
}
